-- BeeHero — Мій дім / Бджоли
INSERT INTO `products` (`name`, `logo_url`, `official_url`, `internal_registration_url`, `affiliate_url`, `short_description`, `short_description_en`, `full_description`, `full_description_en`, `main_features`, `main_features_en`, `target_audience`, `target_audience_en`, `platform`, `skill_level`, `status`, `is_archived`, `partnership_status`, `created_at`, `created_by`) SELECT 'BeeHero', NULL, 'https://beehero.io', NULL, NULL, 'AI-платформа точного запилення для комерційних фермерів із моніторингом активності бджіл через сенсори у вуликах. Ціна не розкрита публічно.', NULL, 'BeeHero керує понад 300 000 вуликів на 200 000+ акрах, збираючи мільйони точок даних щодня через сенсори. Пропонує розміщення вуликів під час цвітіння та вимірювання відвідувань квітів бджолами для насіннєвих і плодових культур.', NULL, 'Моніторинг активності бджіл через сенсори у вуликах
Дані про силу колонії та ефективність запилення в реальному часі
Precision Pollination as a Service для розміщення вуликів
Аналітика для насіннєвих і плодових культур', NULL, 'Комерційні фермери, що вирощують культури, залежні від запилення', NULL, 'web,mobile', 'basic', 'published', '0', 'no_partnership', '2026-09-15 20:00:00', (SELECT `id` FROM `users` WHERE `email` = 'whitevelvetelf@gmail.com' LIMIT 1) FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'beehero.io' OR LOWER(`name`) = LOWER('BeeHero')));
SET @new = ROW_COUNT();
SET @pid = (SELECT `id` FROM `products` WHERE (LOWER(TRIM(TRAILING '/' FROM REPLACE(REPLACE(REPLACE(REPLACE(`official_url`, 'https://www.', ''), 'http://www.', ''), 'https://', ''), 'http://', ''))) = 'beehero.io' OR LOWER(`name`) = LOWER('BeeHero')) ORDER BY `id` LIMIT 1);
INSERT IGNORE INTO `product_categories` (`product_id`, `category_id`) SELECT @pid, c.`id` FROM `categories` c WHERE @pid IS NOT NULL AND (c.`slug` = 'my-home' OR c.`name` = 'Мій дім') ORDER BY c.`slug` = 'my-home' DESC LIMIT 1;
INSERT IGNORE INTO `product_subcategories` (`product_id`, `subcategory_id`) SELECT @pid, s.`id` FROM `subcategories` s JOIN `categories` c ON c.`id` = s.`category_id` WHERE @pid IS NOT NULL AND (c.`slug` = 'my-home' OR c.`name` = 'Мій дім') AND (s.`slug` = 'beekeeping' OR s.`name` = 'Бджоли') ORDER BY s.`slug` = 'beekeeping' DESC LIMIT 1;
INSERT INTO `pricing_plans` (`product_id`, `plan_name`, `plan_name_en`, `price`, `period`, `description`, `description_en`) SELECT @pid, 'Enterprise', NULL, 0.00, 'free', 'ціна не розкрита публічно, потрібен контакт із продажами', NULL FROM DUAL WHERE @new = 1;

